-- 小宇网络 WAP建站系统 PHP版 补充数据表 (SQLite)
CREATE TABLE IF NOT EXISTS WapOnline (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, username TEXT DEFAULT '', ip TEXT DEFAULT '', page TEXT DEFAULT '', lasttime TEXT);
CREATE TABLE IF NOT EXISTS WapSignin (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, signdate TEXT, days INTEGER DEFAULT 1, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapMessage (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, fromid INTEGER DEFAULT 0, fromname TEXT DEFAULT '', toid INTEGER DEFAULT 0, toname TEXT DEFAULT '', title TEXT DEFAULT '', content TEXT, isread INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapSysMsg (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, title TEXT DEFAULT '', content TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapFriend (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, friendid INTEGER DEFAULT 0, status INTEGER DEFAULT 1, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapFav (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, module TEXT DEFAULT '', contentid INTEGER DEFAULT 0, title TEXT DEFAULT '', addtime TEXT);
CREATE TABLE IF NOT EXISTS WapVote (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, bbsid INTEGER DEFAULT 0, question TEXT DEFAULT '', total INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS WapVoteOption (id INTEGER PRIMARY KEY AUTOINCREMENT, voteid INTEGER DEFAULT 0, optionname TEXT DEFAULT '', votes INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS WapVoteLog (id INTEGER PRIMARY KEY AUTOINCREMENT, voteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, optionid INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapBbsFile (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, bbsid INTEGER DEFAULT 0, filename TEXT DEFAULT '', filepath TEXT DEFAULT '', filesize INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapChatSpeak (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, nickname TEXT DEFAULT '', content TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapClan (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, name TEXT DEFAULT '', intro TEXT, members INTEGER DEFAULT 1, point INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapClanMember (id INTEGER PRIMARY KEY AUTOINCREMENT, clanid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, nickname TEXT DEFAULT '', role INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapClanChat (id INTEGER PRIMARY KEY AUTOINCREMENT, clanid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, nickname TEXT DEFAULT '', content TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapGames (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, name TEXT DEFAULT '', picurl TEXT DEFAULT '', url TEXT DEFAULT '', intro TEXT, clicks INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapGamesScore (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, gameid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, nickname TEXT DEFAULT '', score INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapCard (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, cardno TEXT DEFAULT '', cardpwd TEXT DEFAULT '', cardtype TEXT DEFAULT '', money INTEGER DEFAULT 0, isused INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, usetime TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapAccountLog (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, type TEXT DEFAULT 'in', num INTEGER DEFAULT 0, balance INTEGER DEFAULT 0, remark TEXT DEFAULT '', addtime TEXT);
CREATE TABLE IF NOT EXISTS WapShopCart (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, shopid INTEGER DEFAULT 0, title TEXT DEFAULT '', price INTEGER DEFAULT 0, num INTEGER DEFAULT 1, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapVisite (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, visitdate TEXT, pv INTEGER DEFAULT 0, uv INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS WapVisiteLog (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, ip TEXT DEFAULT '', url TEXT DEFAULT '', ua TEXT DEFAULT '', addtime TEXT);
CREATE TABLE IF NOT EXISTS WapArticleFile (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, classid INTEGER DEFAULT 0, articleid INTEGER DEFAULT 0, filename TEXT DEFAULT '', filepath TEXT DEFAULT '', filesize INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapForm (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, classid INTEGER DEFAULT 0, name TEXT DEFAULT '', fields TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapFormData (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, formid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, data TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapPageTpl (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, name TEXT DEFAULT '', content TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapDomain (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, domain TEXT DEFAULT '', status INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapTemplate (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT DEFAULT '', dir TEXT DEFAULT '', isdefault INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS WapWeixin (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, appid TEXT DEFAULT '', secret TEXT DEFAULT '', token TEXT DEFAULT '', isopen INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapWeixinMsg (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, fromuser TEXT DEFAULT '', content TEXT, reply TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapSms (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, mobile TEXT DEFAULT '', content TEXT, status INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapCaiji (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, name TEXT DEFAULT '', url TEXT DEFAULT '', classid INTEGER DEFAULT 0, lastrun TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapNongChang (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, level INTEGER DEFAULT 1, exp INTEGER DEFAULT 0, gold INTEGER DEFAULT 100, plots TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapZhiDao (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, classid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, nickname TEXT DEFAULT '', title TEXT DEFAULT '', content TEXT, status INTEGER DEFAULT 0, hits INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapZhiDaoReply (id INTEGER PRIMARY KEY AUTOINCREMENT, zhidoid INTEGER DEFAULT 0, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, nickname TEXT DEFAULT '', content TEXT, isbest INTEGER DEFAULT 0, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapUserLog (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, action TEXT DEFAULT '', content TEXT DEFAULT '', ip TEXT DEFAULT '', addtime TEXT);
CREATE TABLE IF NOT EXISTS WapZone (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, zonename TEXT DEFAULT '', intro TEXT, pic TEXT DEFAULT '', addtime TEXT);
CREATE TABLE IF NOT EXISTS WapZoneMsg (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, zoneid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, nickname TEXT DEFAULT '', content TEXT, addtime TEXT);
CREATE TABLE IF NOT EXISTS WapPaimaiBid (id INTEGER PRIMARY KEY AUTOINCREMENT, siteid INTEGER DEFAULT 0, paimaiid INTEGER DEFAULT 0, userid INTEGER DEFAULT 0, nickname TEXT DEFAULT '', price INTEGER DEFAULT 0, addtime TEXT);
CREATE INDEX IF NOT EXISTS idx_online_site ON WapOnline(siteid,lasttime);
CREATE INDEX IF NOT EXISTS idx_msg_to ON WapMessage(toid,isread);
CREATE INDEX IF NOT EXISTS idx_friend_user ON WapFriend(userid,friendid);
CREATE INDEX IF NOT EXISTS idx_cart_user ON WapShopCart(userid,siteid);
CREATE INDEX IF NOT EXISTS idx_signin_user ON WapSignin(userid,signdate);
CREATE INDEX IF NOT EXISTS idx_zdreply ON WapZhiDaoReply(zhidoid);
